import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';
import api from '../../services/api';

// Async thunks
export const fetchChatSessions = createAsyncThunk(
  'chat/fetchSessions',
  async (_, { rejectWithValue }) => {
    try {
      const response = await api.get('/api/therapy/sessions');
      return response.data;
    } catch (error) {
      return rejectWithValue(error.response?.data?.detail || 'Could not fetch chat sessions');
    }
  }
);

export const fetchChatMessages = createAsyncThunk(
  'chat/fetchMessages',
  async (sessionId, { rejectWithValue }) => {
    try {
      const response = await api.get(`/api/therapy/sessions/${sessionId}`);
      return response.data;
    } catch (error) {
      return rejectWithValue(error.response?.data?.detail || 'Could not fetch chat messages');
    }
  }
);

export const sendChatMessage = createAsyncThunk(
  'chat/sendMessage',
  async ({ message, chatSessionId = null }, { rejectWithValue }) => {
    try {
      const response = await api.post('/api/therapy/chat', {
        message,
        chat_session_id: chatSessionId,
        stream: false  // Regular non-streaming request
      });
      return response.data;
    } catch (error) {
      return rejectWithValue(error.response?.data?.detail || 'Could not send message');
    }
  }
);

// Add a streaming message thunk
export const streamChatMessage = createAsyncThunk(
  'chat/streamMessage',
  async ({ message, chatSessionId = null }, { dispatch, rejectWithValue }) => {
    try {
      // Start the streaming response
      dispatch(startStreaming());
      
      // Make a fetch request to use with EventSource
      const response = await fetch(`${api.defaults.baseURL}/api/therapy/chat`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(localStorage.getItem('token') ? { 
            Authorization: `Bearer ${localStorage.getItem('token')}` 
          } : {})
        },
        body: JSON.stringify({
          message,
          chat_session_id: chatSessionId,
          stream: true  // Request streaming response
        })
      });
      
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      
      // Get the reader from the response
      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let sessionId = chatSessionId;
      
      // Read the stream
      while (true) {
        const { done, value } = await reader.read();
        if (done) {
          break;
        }
        
        // Decode the chunk
        const chunk = decoder.decode(value);
        
        // Process each line (server-sent event)
        const lines = chunk.split('\n\n');
        for (const line of lines) {
          if (line.startsWith('data:')) {
            try {
              // Parse the data
              const data = JSON.parse(line.slice(5).trim());
              
              // Check if it's the done marker
              if (data.done) {
                dispatch(endStreaming());
                break;
              }
              
              // Stream the chunk
              if (data.chunk) {
                dispatch(streamChunk(data.chunk));
              }
              
              // Update session ID if available
              if (data.chat_session_id && !sessionId) {
                sessionId = data.chat_session_id;
                dispatch(setCurrentSession(sessionId));
              }
            } catch (e) {
              console.error('Error parsing SSE data:', e);
            }
          }
        }
      }
      
      // Return the session ID
      return { sessionId };
    } catch (error) {
      dispatch(endStreaming());
      return rejectWithValue(error.message || 'Could not stream message');
    }
  }
);

const chatSlice = createSlice({
  name: 'chat',
  initialState: {
    sessions: [],
    currentSession: null,
    messages: [],
    isLoading: false,
    isStreaming: false,  // New state for streaming
    currentStreamedMessage: '',  // Buffer for current message being streamed
    error: null
  },
  reducers: {
    setCurrentSession: (state, action) => {
      state.currentSession = action.payload;
    },
    clearChatError: (state) => {
      state.error = null;
    },
    addMessage: (state, action) => {
      state.messages.push(action.payload);
    },
    // New reducers for streaming
    startStreaming: (state) => {
      state.isStreaming = true;
      state.currentStreamedMessage = '';
    },
    streamChunk: (state, action) => {
      state.currentStreamedMessage += action.payload;
    },
    endStreaming: (state) => {
      // When streaming ends, add the complete streamed message as a regular message
      if (state.currentStreamedMessage) {
        state.messages.push({
          role: 'assistant',
          content: state.currentStreamedMessage,
          timestamp: new Date().toISOString()
        });
      }
      state.isStreaming = false;
      state.currentStreamedMessage = '';
    }
  },
  extraReducers: (builder) => {
    builder
      // Fetch sessions
      .addCase(fetchChatSessions.pending, (state) => {
        state.isLoading = true;
        state.error = null;
      })
      .addCase(fetchChatSessions.fulfilled, (state, action) => {
        state.isLoading = false;
        state.sessions = action.payload;
      })
      .addCase(fetchChatSessions.rejected, (state, action) => {
        state.isLoading = false;
        state.error = action.payload;
      })
      
      // Fetch messages
      .addCase(fetchChatMessages.pending, (state) => {
        state.isLoading = true;
        state.error = null;
      })
      .addCase(fetchChatMessages.fulfilled, (state, action) => {
        state.isLoading = false;
        state.currentSession = action.payload.id;
        state.messages = action.payload.messages;
      })
      .addCase(fetchChatMessages.rejected, (state, action) => {
        state.isLoading = false;
        state.error = action.payload;
      })
      
      // Send message
      .addCase(sendChatMessage.pending, (state) => {
        state.isLoading = true;
        state.error = null;
      })
      .addCase(sendChatMessage.fulfilled, (state, action) => {
        state.isLoading = false;
        state.currentSession = action.payload.chat_session_id;
        state.messages.push({
          role: 'assistant',
          content: action.payload.response,
          timestamp: new Date().toISOString()
        });
      })
      .addCase(sendChatMessage.rejected, (state, action) => {
        state.isLoading = false;
        state.error = action.payload;
      })
      
      // Stream message
      .addCase(streamChatMessage.pending, (state) => {
        state.error = null;
      })
      .addCase(streamChatMessage.fulfilled, (state, action) => {
        if (action.payload?.sessionId) {
          state.currentSession = action.payload.sessionId;
        }
      })
      .addCase(streamChatMessage.rejected, (state, action) => {
        state.error = action.payload;
      });
  }
});

export const { 
  setCurrentSession, 
  clearChatError, 
  addMessage,
  startStreaming,
  streamChunk,
  endStreaming 
} = chatSlice.actions;

export default chatSlice.reducer;
